INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Unit-Tests nur für kleine Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch große Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Integrationstests?', 3, '[{"text": "Zusammenspiel von Modulen prüfen", "correct": true, "because": "Sichert Interaktion"}, {"text": "Einzelmodule testen", "correct": false, "because": "Unit-Test-Fokus"}, {"text": "UI verbessern", "correct": false, "because": "Kein Design-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testarten decken das Gesamtsystem ab?', 5, '[{"text": "Unit-Tests", "correct": false, "because": "Einzelmodule"}, {"text": "Integrationstests", "correct": false, "because": "Zusammenspiel"}, {"text": "Systemtests", "correct": true, "because": "Gesamtsystem prüfen"}, {"text": "UI-Tests", "correct": false, "because": "Design-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unit-Tests prüfen Einzelmodule. b) Sie ersetzen Systemtests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Systemtests separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Unit-Tests?', 4, '[{"text": "Modulisolation", "correct": false, "because": "Kern der Tests"}, {"text": "Fehlererkennung", "correct": false, "because": "Hauptziel"}, {"text": "UI-Design", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Systemtests ohne Integrationstests möglich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Direkt machbar"}, {"text": "Nein", "correct": false, "because": "Integration hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel haben Systemtests?', 3, '[{"text": "Gesamtsystem prüfen", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Einzelmodule testen", "correct": false, "because": "Unit-Test-Fokus"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Integrationstests?', 5, '[{"text": "Modulinteraktion prüfen", "correct": true, "because": "Sichert Zusammenspiel"}, {"text": "Frühe Fehlererkennung", "correct": true, "because": "Zwischen Module"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Unit-Tests sind schnell. b) Sie testen das Gesamtsystem. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Systemtests für Gesamt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Systemtests?', 4, '[{"text": "Gesamtsystem", "correct": false, "because": "Kern der Tests"}, {"text": "Testumgebung", "correct": false, "because": "Simuliert Realität"}, {"text": "Farbanimationen", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Unit-Tests ohne Tools möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell machbar"}, {"text": "Nein", "correct": false, "because": "Tools nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme lösen Integrationstests?', 4, '[{"text": "Modulfehler", "correct": true, "because": "Interaktion prüfen"}, {"text": "Schnittstellenprobleme", "correct": true, "because": "Zusammenspiel testen"}, {"text": "Langsame Server", "correct": false, "because": "Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Systemtests nur für Kunden sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch intern nützlich"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Unit-Tests?', 3, '[{"text": "Isolation", "correct": true, "because": "Einzelmodule prüfen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Testfälle", "correct": false, "because": "Relevanz entscheidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemtests prüfen End-to-End. b) Sie ersetzen Unit-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unit-Tests separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Integrationstests?', 5, '[{"text": "Höherer Aufwand", "correct": true, "because": "Mehr Komponenten"}, {"text": "Komplexere Umgebung", "correct": true, "because": "Interaktion testen"}, {"text": "Langsamere Builds", "correct": false, "because": "Kein Build-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Unit-Tests unwichtig?', 3, '[{"text": "Modulisolation", "correct": false, "because": "Kernziel"}, {"text": "Fehlererkennung", "correct": false, "because": "Hauptfokus"}, {"text": "UI-Layout", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Systemtests den Testaufwand?', 3, '[{"text": "Ja", "correct": true, "because": "Gesamtsystem prüfen"}, {"text": "Nein", "correct": false, "because": "Aufwand steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Integrationstests Fehler finden?', 2, '[{"text": "Ja", "correct": true, "because": "Zwischen Modulen"}, {"text": "Nein", "correct": false, "because": "Klarer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei Unit-Tests?', 4, '[{"text": "JUnit", "correct": true, "because": "Automatisiert Unit-Tests"}, {"text": "Selenium", "correct": false, "because": "UI-Fokus"}, {"text": "Compiler", "correct": false, "because": "Nur Syntax"}]');
